package com.hmdp.ai.runtime.tool.skill;
import com.fasterxml.jackson.databind.*;import com.hmdp.ai.port.*;import com.hmdp.ai.runtime.tool.skill.dto.ReviewEvidenceData;import com.hmdp.dto.ai.ReviewDoc;import java.util.*;import java.util.stream.Collectors;
abstract class ShopSkillSupport {protected final ShopDataPort shops;protected final ReviewDataPort reviews;protected final ObjectMapper mapper;ShopSkillSupport(ShopDataPort shops,ReviewDataPort reviews,ObjectMapper mapper){this.shops=shops;this.reviews=reviews;this.mapper=mapper;}protected long shopId(JsonNode in){long id=in.path("shopId").asLong(0);if(id<=0)throw new IllegalArgumentException("shopId must be positive");return id;}protected List<ReviewEvidenceData> evidence(List<ReviewDoc> docs){if(docs==null)return Collections.emptyList();return docs.stream().filter(Objects::nonNull).map(d->new ReviewEvidenceData(d.getId(),d.getTitle(),d.getContent(),d.getLiked(),d.getCreateTime())).collect(Collectors.toList());}protected JsonNode json(Object value){return mapper.valueToTree(value);}}
